function addProjectGalleryItem(project, item = {}) {
  const targetProject = project || state.project;
  const normalized = createGalleryItem({
    ...item,
    projectId: item.projectId || targetProject.id || state.projects.activeId || "",
    source: "generated",
    metadata: { ...(item.metadata || {}), generated: item.metadata?.generated ?? true },
  });
  if (targetProject === state.project) {
    return upsertGalleryItem(normalized);
  }
  targetProject.gallery = safeArray(targetProject.gallery);
  const index = targetProject.gallery.findIndex((entry) => entry.id === normalized.id);
  if (index >= 0) targetProject.gallery[index] = { ...targetProject.gallery[index], ...normalized, updatedAt: new Date().toISOString() };
  else targetProject.gallery.unshift(normalized);
  return normalized;
}

function addProjectAsset(project, asset = {}) {
  const targetProject = project || state.project;

  if (
    asset.source === "ai-generated" ||
    asset.source === "generated" ||
    asset.generated === true ||
    asset.output === true ||
    ["render", "base_image", "clip", "video", "pdf", "pptx", "brochure"].includes(asset.type)
  ) {
    throw new Error("ASSET_POLICY_ERROR::Generated outputs must go to Gallery, not Assets.");
  }

  const normalized = normalizeAsset({
    ...asset,
    id: asset.id || createId("asset"),
    source: asset.source || "user-uploaded",
    createdAt: asset.createdAt || new Date().toISOString(),
  }, targetProject.id || state.projects.activeId || "");
  targetProject.assets = safeArray(targetProject.assets);
  targetProject.assets.push(normalized);
  return normalized;
}

function getBrochureImageLayerOriginalUrl(layer) {
  if (!layer) return "";
  const source = findProjectMediaItem(layer.sourceAssetId || layer.sourceGalleryItemId || layer.metadata?.sourceItemId);
  return source?.dataUrl || source?.url || layer.originalSrc || layer.src || "";
}

function getBrochureImageLayerRenderedUrl(layer) {
  if (!layer?.renderedAssetId) return "";
  const rendered = findProjectMediaItem(layer.renderedAssetId);
  return rendered?.dataUrl || rendered?.url || "";
}

function getBrochureImageLayerUrl(layer) {
  if (!layer) return "";
  return layer.renderMode === "rendered" ? (getBrochureImageLayerRenderedUrl(layer) || layer.src || "") : (layer.src || getBrochureImageLayerOriginalUrl(layer));
}

function getProjectMediaSrc(item) {
  return item?.url || item?.dataUrl || item?.thumbnailUrl || "";
}

function getProjectMediaDisplayName(item, fallback = "Imagen") {
  return item?.name || item?.fileName || item?.metadata?.originalName || fallback;
}

function upsertGalleryItem(itemInput = {}) {
  const item = createGalleryItem(itemInput);
  const index = state.project.gallery.findIndex((entry) => entry.id === item.id);
  if (index >= 0) {
    state.project.gallery[index] = { ...state.project.gallery[index], ...item, updatedAt: new Date().toISOString() };
  } else {
    state.project.gallery.unshift(item);
  }
  state.project.updatedAt = new Date().toISOString();
  console.info("[Gallery] count", state.project.gallery.length);
  return item;
}

function markDependentsOutdated(project, galleryItemId) {
  for (const item of safeArray(project.gallery)) {
    if (safeArray(item.parentGalleryItemIds).includes(galleryItemId) && item.status !== "deleted") {
      item.status = "outdated";
      item.updatedAt = new Date().toISOString();
      markDependentsOutdated(project, item.id);
    }
  }
}

function deleteGalleryItem(project, itemId) {
  const item = safeArray(project.gallery).find((entry) => entry.id === itemId);
  if (!item) return;
  item.status = "deleted";
  item.updatedAt = new Date().toISOString();
  markDependentsOutdated(project, itemId);
  scheduleProjectAutosave("gallery-delete");
}

