function createCreativeEditorId(prefix = "el") {
  const randomPart = Math.random().toString(36).slice(2, 8);
  return `${prefix}-${Date.now().toString(36)}-${randomPart}`;
}

function cloneCreativeEditorValue(value, fallback = {}) {
  try {
    return JSON.parse(JSON.stringify(value ?? fallback));
  } catch {
    return JSON.parse(JSON.stringify(fallback));
  }
}

function numberOr(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function cssUrl(value) {
  return String(value || "").replace(/"/g, "%22");
}

function normalizeCreativeElement(element, index = 0) {
  const type = ["text", "image", "shape", "palette"].includes(element?.type) ? element.type : "shape";
  const style = element?.style || {};
  const resolvedSrc = element?.src || element?.url || "";
  return {
    id: element?.id || createCreativeEditorId(type),
    name: element?.name || (type === "text" ? "Texto" : type === "image" ? "Imagen" : "Forma"),
    role: element?.role || element?.metadata?.role || "",
    type,
    shapeType: element?.shapeType || element?.metadata?.shapeType || "",
    x: clamp(numberOr(element?.x, 80), 0, CREATIVE_EDITOR_SIZE.width),
    y: clamp(numberOr(element?.y, 80), 0, CREATIVE_EDITOR_SIZE.height),
    width: clamp(numberOr(element?.width, 220), 20, CREATIVE_EDITOR_SIZE.width),
    height: clamp(numberOr(element?.height, 90), 20, CREATIVE_EDITOR_SIZE.height),
    rotation: numberOr(element?.rotation, 0),
    zIndex: numberOr(element?.zIndex, index + 1),
    opacity: clamp(numberOr(element?.opacity, 1), 0.05, 1),
    visible: element?.visible !== false,
    locked: Boolean(element?.locked),
    content: element?.content || element?.text || (type === "text" ? "Texto editable" : ""),
    src: resolvedSrc,
    originalSrc: element?.originalSrc || resolvedSrc,
    objectFit: element?.objectFit || "cover",
    slotInstanceId: type === "image" ? (element?.slotInstanceId || createId("slot")) : null,
    sourceAssetId: element?.sourceAssetId || element?.assetId || element?.metadata?.sourceItemId || "",
    sourceGalleryItemId: element?.sourceGalleryItemId || "",
    renderedAssetId: element?.renderedAssetId || element?.metadata?.renderedGalleryItemId || "",
    renderMode: type === "image" ? (element?.renderMode || (element?.renderedAssetId ? "rendered" : "original")) : undefined,
    renderHistory: type === "image" ? safeArray(element?.renderHistory) : undefined,
    photoSettings: type === "image" ? cloneCreativeEditorValue(element?.photoSettings || {}, {}) : undefined,
    metadata: cloneCreativeEditorValue(element?.metadata || {}, {}),
    colors: safeArray(element?.colors),
    style: {
      fontFamily: style.fontFamily || (type === "text" ? (state.settings.titleFont || "Fraunces") : "Manrope"),
      fontSize: numberOr(style.fontSize, type === "text" ? 34 : 16),
      fontWeight: style.fontWeight || (type === "text" ? "700" : "500"),
      fontStyle: style.fontStyle || "normal",
      textDecoration: style.textDecoration || "none",
      color: style.color || "#181715",
      backgroundColor: style.backgroundColor || style.fill || (type === "shape" ? "#F4F1EA" : "transparent"),
      borderColor: style.borderColor || style.stroke || "transparent",
      borderWidth: numberOr(style.borderWidth ?? style.strokeWidth, 0),
      borderRadius: numberOr(style.borderRadius ?? style.radius, type === "image" ? 22 : 10),
      textAlign: style.textAlign || style.align || "left",
      lineHeight: style.lineHeight || 1.15,
      letterSpacing: numberOr(style.letterSpacing, 0),
    },
  };
}

function normalizeCreativeSlide(slide, index = 0) {
  const elements = safeArray(slide?.elements || slide?.layers).map((element, elementIndex) => normalizeCreativeElement(element, elementIndex));
  return {
    id: slide?.id || createCreativeEditorId("slide"),
    name: slide?.name || slide?.title || `Diapositiva ${index + 1}`,
    sectionId: slide?.sectionId || slide?.key || "",
    layout: slide?.layout || slide?.activeLayout || "",
    background: slide?.background?.type ? slide.background : { type: "color", value: "#FFFFFF" },
    elements,
  };
}

function getCreativeEditorImages() {
  const selectedIds = safeArray(state.projectUi?.presentationSelectedAssetIds);
  const projectSources = selectedIds.length
    ? selectedIds.map(findProjectMediaItem).filter(Boolean)
    : getProjectPresentationAssets();
  const projectImages = safeArray(projectSources)
    .filter((item) => {
      const mimeType = String(item?.mimeType || "");
      return ["image", "render", "base_image", "reference"].includes(item?.type) || mimeType.startsWith("image/");
    })
    .map((item, index) => ({
      id: item.id || `project-image-${index}`,
      name: getProjectMediaDisplayName(item, `Imagen ${index + 1}`),
      src: getProjectMediaSrc(item),
      sourceType: getAssetById(item.id) ? "asset" : "gallery",
      analysis: item.analysis || item.metadata?.analysis || null,
      metadata: item.metadata || {},
    }))
    .filter((image) => image.src);
  const legacyImages = safeArray(state.images).map((image, index) => ({
    id: image.id || `image-${index}`,
    name: image.name || image.fileName || `Imagen ${index + 1}`,
    src: image.url || image.dataUrl || "",
    sourceType: "legacy",
  })).filter((image) => image.src);
  const seen = new Set();
  return [...projectImages, ...legacyImages].filter((image) => {
    const key = image.id || image.src;
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function getCreativeEditorPalette() {
  return unique([...(state.settings.selectedPalette || []), ...CREATIVE_EDITOR_PALETTE]).slice(0, 10);
}

function makeCreativeElement(type, overrides = {}) {
  return normalizeCreativeElement({
    type,
    id: createCreativeEditorId(type),
    name: type === "text" ? "Texto editable" : type === "image" ? "Imagen editable" : "Forma editable",
    x: type === "text" ? 80 : 110,
    y: type === "text" ? 72 : 98,
    width: type === "text" ? 300 : 260,
    height: type === "text" ? 118 : 160,
    zIndex: 20,
    content: type === "text" ? "Nuevo texto" : "",
    style: {
      fontFamily: type === "text" ? (state.settings.titleFont || "Fraunces") : "Manrope",
      fontSize: type === "text" ? 36 : 16,
      fontWeight: type === "text" ? "700" : "500",
      color: "#181715",
      backgroundColor: type === "shape" ? "#F4F1EA" : "transparent",
      borderRadius: type === "shape" ? 14 : 18,
      textAlign: "left",
    },
    ...overrides,
  });
}

function normalizeLayerFromTemplate(templateLayer, index = 0, images = []) {
  const imagePool = safeArray(images);
  const image = imagePool.length ? imagePool[index % imagePool.length] : null;
  const type = templateLayer?.type || "shape";
  const style = templateLayer?.style || {};
  const src = type === "image" ? (templateLayer.src || image?.src || "") : "";
  return makeCreativeElement(type, {
    name: templateLayer.name || templateLayer.role || type,
    role: templateLayer.role || "",
    x: templateLayer.x,
    y: templateLayer.y,
    width: templateLayer.width,
    height: templateLayer.height,
    zIndex: templateLayer.zIndex,
    content: templateLayer.text || templateLayer.content || "",
    src,
    originalSrc: src,
    objectFit: templateLayer.objectFit || "cover",
    sourceAssetId: image?.sourceType === "asset" ? image.id : "",
    sourceGalleryItemId: image?.sourceType === "gallery" ? image.id : "",
    metadata: { sourceItemId: image?.id || "", sourceType: image?.sourceType || "", role: templateLayer.role || "" },
    colors: safeArray(templateLayer.colors),
    style: {
      fontFamily: type === "text" ? (state.settings.titleFont || "Fraunces") : "Manrope",
      fontSize: style.fontSize,
      fontWeight: style.fontWeight ? String(style.fontWeight) : undefined,
      color: style.color,
      backgroundColor: style.fill || style.backgroundColor,
      borderColor: style.stroke,
      borderWidth: style.strokeWidth,
      borderRadius: style.radius ?? style.borderRadius,
      textAlign: style.align || style.textAlign,
      lineHeight: style.lineHeight,
      letterSpacing: style.letterSpacing,
    },
  });
}

function preserveCompatibleLayerContent(oldSlide, newSlide) {
  if (!oldSlide || !safeArray(oldSlide.elements).length) return newSlide;
  const oldByRole = new Map();
  safeArray(oldSlide.elements).forEach((layer) => {
    if (layer.role && !oldByRole.has(layer.role)) oldByRole.set(layer.role, layer);
  });
  newSlide.elements = safeArray(newSlide.elements).map((newLayer) => {
    const oldLayer = oldByRole.get(newLayer.role);
    if (!oldLayer || oldLayer.type !== newLayer.type) return newLayer;
    if (newLayer.type === "text") {
      return { ...newLayer, content: oldLayer.content || newLayer.content, style: { ...newLayer.style, ...(oldLayer.style || {}) } };
    }
    if (newLayer.type === "image") {
      return {
        ...newLayer,
        src: oldLayer.src || newLayer.src,
        originalSrc: oldLayer.originalSrc || oldLayer.src || newLayer.originalSrc,
        sourceAssetId: oldLayer.sourceAssetId || newLayer.sourceAssetId,
        sourceGalleryItemId: oldLayer.sourceGalleryItemId || newLayer.sourceGalleryItemId,
        renderedAssetId: oldLayer.renderedAssetId || "",
        renderMode: oldLayer.renderMode || "original",
        photoSettings: oldLayer.photoSettings || {},
        renderHistory: safeArray(oldLayer.renderHistory),
        metadata: { ...(newLayer.metadata || {}), ...(oldLayer.metadata || {}) },
      };
    }
    return { ...newLayer, style: { ...newLayer.style, ...(oldLayer.style || {}) } };
  });
  return newSlide;
}

function createSlideFromVariant(slideType, variantId, existingSlide = null) {
  const typeDefinition = BROCHURE_SLIDE_TYPES[slideType] || BROCHURE_SLIDE_TYPES.cover;
  const variant = typeDefinition.variants.find((item) => item.id === variantId) || typeDefinition.variants[0];
  const images = getCreativeEditorImages();
  const slide = normalizeCreativeSlide({
    id: existingSlide?.id || createCreativeEditorId("slide"),
    name: existingSlide?.name || typeDefinition.label,
    sectionId: slideType,
    layout: variant.id,
    layoutVariantId: variant.id,
    background: existingSlide?.background || { type: "color", value: "#FFFDF8" },
    elements: safeArray(variant.layers).map((layer, index) => normalizeLayerFromTemplate(layer, index, images)),
  }, 0);
  return preserveCompatibleLayerContent(existingSlide, slide);
}

const PRESENTATION_LAYOUT_LIBRARY = BROCHURE_SLIDE_TYPES;

function normalizePresentationLayer(templateLayer) {
  const layer = normalizeCreativeElement(templateLayer);
  layer.text = layer.content || templateLayer?.text || "";
  if (layer.type === "image") {
    layer.slotInstanceId = layer.slotInstanceId || createId("slot");
    layer.assetId = layer.assetId || layer.sourceAssetId || null;
    layer.renderedAssetId = layer.renderedAssetId || null;
    layer.renderMode = layer.renderMode || "original";
    layer.renderSettings = layer.renderSettings || {};
    layer.renderHistory = safeArray(layer.renderHistory);
  }
  return layer;
}

function createSlideFromLayout(slideType, variantId, existingSlide = null) {
  const slide = createSlideFromVariant(slideType, variantId, existingSlide);
  slide.slideType = slide.sectionId || slideType;
  slide.layoutVariantId = slide.layout || variantId;
  slide.layers = slide.elements;
  return slide;
}

function createPresentationState(project) {
  const firstSlide = createSlideFromLayout("cover", "cover-editorial-split");

  return {
    id: createId("presentation"),
    title: project?.name || "Presentacion",
    mode: "brochure",
    aspectRatio: "16:9",
    slides: [firstSlide],
    selectedSlideId: firstSlide.id,
    selectedLayerId: firstSlide.layers[0]?.id || null,
    activeTab: "home",
    clipboard: null,
    settings: {},
    exportHistory: [],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
}

function getSelectedPresentation(project) {
  if (!project.presentationState) {
    project.presentationState = createPresentationState(project);
  }
  return project.presentationState;
}

function getSelectedSlide(presentation) {
  return safeArray(presentation.slides).find((slide) => slide.id === presentation.selectedSlideId) || presentation.slides[0] || null;
}

function getSelectedLayer(presentation) {
  const slide = getSelectedSlide(presentation);
  const layers = safeArray(slide?.layers || slide?.elements);
  return layers.find((layer) => layer.id === presentation.selectedLayerId) || null;
}

function addLayerToSlide(project, layerTemplate) {
  const presentation = getSelectedPresentation(project);
  const slide = getSelectedSlide(presentation);
  if (!slide) return null;

  slide.layers = slide.layers || slide.elements || [];
  slide.elements = slide.elements || slide.layers;
  const maxZ = Math.max(0, ...safeArray(slide.layers).map((layer) => Number(layer.zIndex) || 0));
  const layer = normalizePresentationLayer({
    ...layerTemplate,
    zIndex: maxZ + 1,
  });

  slide.layers.push(layer);
  if (slide.elements !== slide.layers) slide.elements.push(layer);
  presentation.selectedLayerId = layer.id;
  slide.updatedAt = new Date().toISOString();
  presentation.updatedAt = new Date().toISOString();
  scheduleProjectAutosave("presentation-layer");
  renderAll();
  return layer;
}

