function templateObjectToCreativeRect(obj = {}) {
  const rect = clampTemplateRect(obj);
  return {
    x: Math.round((rect.x / 100) * CREATIVE_EDITOR_SIZE.width),
    y: Math.round((rect.y / 100) * CREATIVE_EDITOR_SIZE.height),
    width: Math.max(24, Math.round((rect.width / 100) * CREATIVE_EDITOR_SIZE.width)),
    height: Math.max(18, Math.round((rect.height / 100) * CREATIVE_EDITOR_SIZE.height)),
  };
}

function buildCreativeTemplateElementsFromLocalTemplateSlide(layoutId, seed = {}) {
  const entry = getSelectedLocalTemplateEntry();
  const activeLayout = layoutId || "tpl-page-1";
  if (!entry || entry.blank || activeLayout === "blank-canvas") {
    return buildCreativeTemplateElements(seed.templateId || "cover", seed);
  }

  const config = state.settings.pdfSlideConfigs?.[seed.blueprintKey || seed.sectionId || ""] || {};
  const editable = resolveTemplateEditableObjects(entry, activeLayout, config);
  const textObjects = safeArray(editable.textObjects);
  const imageSlots = safeArray(editable.imageSlots).filter((slot) => slot.id !== "__background__" || safeArray(seed.images).length || getCreativeEditorImages().length);
  const sourceObjects = getLocalTemplateSlideObjects(entry, activeLayout);
  const templateHasImageIntent = sourceObjects.some(hasTemplateImageIntent);

  if ((!textObjects.length && imageSlots.length <= 1) || (!templateHasImageIntent && safeArray(seed.images).length)) {
    return buildCreativeTemplateElements(seed.templateId || "cover", seed);
  }

  const palette = safeArray(seed.palette).length ? seed.palette : getCreativeEditorPalette();
  const images = safeArray(seed.images).length ? seed.images : getCreativeEditorImages();
  const title = seed.title || state.settings.contextBrief || "Titulo del proyecto";
  const subtitle = seed.subtitle || state.settings.brochureIdea || "Narrativa visual del proyecto.";
  const bullets = safeArray(seed.bullets).length ? seed.bullets : [
    state.settings.targetAudience ? `Publico: ${state.settings.targetAudience}` : "Lectura del proyecto",
    "Materialidad y atmosfera",
    "Imagenes editables del proyecto",
  ];

  const elements = [
    makeCreativeElement("shape", {
      name: "Fondo editable",
      x: 0,
      y: 0,
      width: CREATIVE_EDITOR_SIZE.width,
      height: CREATIVE_EDITOR_SIZE.height,
      zIndex: 1,
      style: { backgroundColor: palette[0] || "#FFFFFF", borderRadius: 0 },
    }),
  ];

  imageSlots.forEach((slot, index) => {
    const rect = templateObjectToCreativeRect(slot);
    const fallbackIndex = templateSlotFallbackIndex(slot, index);
    const image = images[fallbackIndex] || images[index % Math.max(1, images.length)] || null;
    elements.push(makeCreativeElement("image", {
      name: labelTemplateImageSlot(slot, index),
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: rect.height,
      zIndex: 20 + numberOr(slot.z, index),
      src: image?.src || "",
      style: { borderRadius: slot.role === "background" ? 0 : 10 },
    }));
  });

  textObjects.forEach((obj, index) => {
    const rect = templateObjectToCreativeRect(obj);
    const role = String(obj.role || obj.name || "").toLowerCase();
    const fallbackText = role.includes("title")
      ? title
      : role.includes("subtitle")
        ? subtitle
        : bullets[index % Math.max(1, bullets.length)] || obj.text || "Texto editable";
    const content = config.templateTextOverrides?.[obj.id] || fallbackText || obj.text || "Texto editable";
    const align = String(obj.style?.align || "left").toLowerCase();
    elements.push(makeCreativeElement("text", {
      name: obj.name || `Texto ${index + 1}`,
      x: rect.x,
      y: rect.y,
      width: rect.width,
      height: Math.max(rect.height, 34),
      zIndex: 120 + numberOr(obj.z, index),
      content,
      style: {
        fontFamily: obj.style?.fontFamily || (role.includes("title") ? state.settings.titleFont : state.settings.bodyFont) || "Manrope",
        fontSize: clamp(numberOr(obj.style?.fontSize, role.includes("title") ? 34 : 18), 9, 64),
        fontWeight: obj.style?.bold ? "700" : (role.includes("title") ? "700" : "500"),
        color: obj.style?.color || "#181715",
        backgroundColor: "transparent",
        borderRadius: 0,
        textAlign: align.includes("center") ? "center" : align.includes("right") ? "right" : "left",
      },
    }));
  });

  return elements.sort((a, b) => numberOr(a.zIndex, 0) - numberOr(b.zIndex, 0));
}

function createCreativeSlideFromBlueprint(blueprint, index, analysis) {
  const config = state.settings.pdfSlideConfigs?.[blueprint.key] || {};
  const activeImageId = resolveSlideActiveImageId(config);
  const selectedImages = safeArray(config.imageIds)
    .map((imageId) => findProjectMediaItem(imageId) || state.images.find((image) => image.id === imageId))
    .filter(Boolean)
    .map((image) => ({ id: image.id, name: getProjectMediaDisplayName(image), src: getProjectMediaSrc(image) || image.url || image.dataUrl || "" }))
    .filter((image) => image.src);
  const editorImages = getCreativeEditorImages();
  const fallbackImage = findProjectMediaItem(activeImageId)
    || state.images.find((image) => image.id === activeImageId)
    || editorImages[index % Math.max(1, editorImages.length)]
    || state.images[index % Math.max(1, state.images.length)];
  const images = selectedImages.length ? selectedImages : (fallbackImage ? [{ id: fallbackImage.id, name: getProjectMediaDisplayName(fallbackImage), src: getProjectMediaSrc(fallbackImage) || fallbackImage.src || fallbackImage.url || fallbackImage.dataUrl || "" }] : []);
  const text = getSlideTextDraft(blueprint, analysis);
  const sectionId = blueprint.sectionId || blueprint.key || "";
  const templateId = index === 0 || sectionId.includes("cover")
    ? "cover"
    : ["moodboard", "materials", "pantone", "concept"].some((token) => sectionId.includes(token) || blueprint.visualRole === token)
      ? "moodboard"
      : "technical";
  const activeLayout = state.settings.pdfSlideLayouts?.[blueprint.key] || `tpl-page-${index + 1}`;
  const elementSeed = {
    title: text.title || blueprint.title,
    subtitle: text.subtitle || blueprint.subtitle,
    bullets: text.bullets || [],
    images,
    palette: getCreativeEditorPalette(),
    templateId,
    blueprintKey: blueprint.key,
    sectionId,
  };
  return normalizeCreativeSlide({
    id: blueprint.key || createCreativeEditorId("slide"),
    name: text.title || blueprint.title || `Diapositiva ${index + 1}`,
    sectionId,
    background: { type: "color", value: "#FFFFFF" },
    layout: activeLayout,
    elements: String(activeLayout).startsWith("tpl-page-")
      ? buildCreativeTemplateElementsFromLocalTemplateSlide(activeLayout, elementSeed)
      : buildCreativeTemplateElements(templateId, elementSeed),
  }, index);
}

function buildCreativeEditorInitialState(blueprints, analysis) {
  const saved = state.settings.deckEditor;
  if (saved?.slides?.length) {
    const slides = safeArray(saved.slides).map((slide, index) => normalizeCreativeSlide(slide, index));
    return {
      title: saved.title || state.settings.contextBrief || "Presentacion editable",
      slides,
      activeSlideId: saved.activeSlideId && slides.some((slide) => slide.id === saved.activeSlideId) ? saved.activeSlideId : slides[0]?.id,
      activeElementId: saved.activeElementId || slides[0]?.elements?.[0]?.id || null,
      activeTab: saved.activeTab || "home",
      zoom: clamp(numberOr(saved.zoom, 72), 45, 120),
    };
  }
  const slides = safeArray(blueprints).map((blueprint, index) => createCreativeSlideFromBlueprint(blueprint, index, analysis));
  return {
    title: state.settings.contextBrief || "Presentacion editable",
    slides,
    activeSlideId: slides[0]?.id || null,
    activeElementId: slides[0]?.elements?.[0]?.id || null,
    activeTab: "home",
    zoom: 72,
  };
}

function buildDeckFromCreativeEditorState(editorState) {
  const slides = safeArray(editorState?.slides).map((slide, index) => {
    const textLayers = safeArray(slide.elements).filter((element) => element.type === "text");
    const imageLayer = safeArray(slide.elements).find((element) => element.type === "image" && element.src);
    return {
      key: slide.id || `slide-${index + 1}`,
      sectionId: slide.sectionId || slide.id || "",
      tag: textLayers[0]?.content || `Slide ${index + 1}`,
      title: textLayers[1]?.content || slide.name || `Slide ${index + 1}`,
      subtitle: textLayers[2]?.content || "",
      bullets: textLayers.slice(3).map((element) => element.content).filter(Boolean).slice(0, 4),
      visualRole: "editable",
      layout: slide.layout || "editable-canvas",
      imageDataUrl: imageLayer?.src || "",
      imageWidth: 0,
      imageHeight: 0,
      editorSource: "creative-deck-editor",
      editorCanvas: { width: CREATIVE_EDITOR_SIZE.width, height: CREATIVE_EDITOR_SIZE.height },
      layerManifest: safeArray(slide.elements).map((element, layerIndex) => ({
        id: element.id,
        layer: layerIndex + 1,
        name: element.name || `Capa ${layerIndex + 1}`,
        role: element.role || "",
        slotInstanceId: element.slotInstanceId || "",
        type: element.type,
        x: element.x,
        y: element.y,
        width: element.width,
        height: element.height,
        rotation: element.rotation || 0,
        zIndex: element.zIndex || layerIndex + 1,
        opacity: element.opacity ?? 1,
        visible: element.visible !== false,
        content: element.content || "",
        src: element.src || "",
        originalSrc: element.originalSrc || "",
        renderedAssetId: element.renderedAssetId || "",
        renderMode: element.renderMode || "",
        renderHistory: safeArray(element.renderHistory),
        photoSettings: cloneCreativeEditorValue(element.photoSettings || {}, {}),
        style: { ...(element.style || {}) },
      })),
    };
  });
  return {
    title: editorState?.title || "Presentacion editable",
    summary: "Deck editable construido por capas en el editor interno.",
    slides,
  };
}

function syncCreativeDeckEditorState(editorState) {
  const serialized = cloneCreativeEditorValue(editorState, null);
  state.settings.deckEditor = serialized;
  state.result.deck = buildDeckFromCreativeEditorState(serialized);
  saveJson(STORAGE_KEYS.settings, state.settings);
  scheduleProjectAutosave("deck-editor");
}

async function buildDeckFromCreativeEditorExportDeck(editorState) {
  const serialized = cloneCreativeEditorValue(editorState, null);
  const deck = buildDeckFromCreativeEditorState(serialized);
  for (let index = 0; index < deck.slides.length; index += 1) {
    const slide = serialized.slides[index];
    try {
      const dataUrl = await renderCreativeSlideToDataUrl(slide, 1600, 900);
      deck.slides[index].composedPageDataUrl = dataUrl;
      deck.slides[index].composedPageWidth = 1600;
      deck.slides[index].composedPageHeight = 900;
      deck.slides[index].imageDataUrl = dataUrl;
      deck.slides[index].imageWidth = 1600;
      deck.slides[index].imageHeight = 900;
    } catch {
      // Keep editable layer export even when a remote image cannot be rasterized.
    }
  }
  return deck;
}

function loadCreativeImage(src) {
  return new Promise((resolve, reject) => {
    if (!src) {
      reject(new Error("Missing image"));
      return;
    }
    const image = new Image();
    if (!String(src).startsWith("data:") && !String(src).startsWith("blob:")) {
      image.crossOrigin = "anonymous";
    }
    image.onload = () => resolve(image);
    image.onerror = reject;
    image.src = src;
  });
}

function drawCreativeRoundRect(ctx, x, y, width, height, radius) {
  const r = Math.min(Math.max(0, radius || 0), width / 2, height / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + width - r, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + r);
  ctx.lineTo(x + width, y + height - r);
  ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
  ctx.lineTo(x + r, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

function drawCreativeImageCover(ctx, image, x, y, width, height, radius = 0) {
  const sourceRatio = image.width / image.height;
  const targetRatio = width / height;
  let sx = 0;
  let sy = 0;
  let sw = image.width;
  let sh = image.height;
  if (sourceRatio > targetRatio) {
    sw = image.height * targetRatio;
    sx = (image.width - sw) / 2;
  } else {
    sh = image.width / targetRatio;
    sy = (image.height - sh) / 2;
  }
  ctx.save();
  drawCreativeRoundRect(ctx, x, y, width, height, radius);
  ctx.clip();
  ctx.drawImage(image, sx, sy, sw, sh, x, y, width, height);
  ctx.restore();
}

function wrapCreativeText(ctx, text, x, y, maxWidth, lineHeight, maxHeight) {
  const paragraphs = String(text || "").split(/\n+/);
  let cursorY = y;
  paragraphs.forEach((paragraph) => {
    const words = paragraph.split(/\s+/).filter(Boolean);
    let line = "";
    words.forEach((word) => {
      const next = line ? `${line} ${word}` : word;
      if (ctx.measureText(next).width > maxWidth && line) {
        if (cursorY + lineHeight <= y + maxHeight) ctx.fillText(line, x, cursorY);
        cursorY += lineHeight;
        line = word;
      } else {
        line = next;
      }
    });
    if (line && cursorY + lineHeight <= y + maxHeight) ctx.fillText(line, x, cursorY);
    cursorY += lineHeight;
  });
}

async function renderCreativeSlideToDataUrl(slide, width = 1600, height = 900) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  const scaleX = width / CREATIVE_EDITOR_SIZE.width;
  const scaleY = height / CREATIVE_EDITOR_SIZE.height;
  const background = slide.background || { type: "color", value: "#FFFFFF" };
  ctx.fillStyle = background.type === "color" ? (background.value || "#FFFFFF") : "#FFFFFF";
  ctx.fillRect(0, 0, width, height);
  if (background.type === "image" && background.value) {
    const image = await loadCreativeImage(background.value);
    drawCreativeImageCover(ctx, image, 0, 0, width, height, 0);
  }
  const layers = safeArray(slide.elements).filter((element) => element.visible !== false).sort((a, b) => numberOr(a.zIndex, 0) - numberOr(b.zIndex, 0));
  for (const element of layers) {
    const x = element.x * scaleX;
    const y = element.y * scaleY;
    const w = element.width * scaleX;
    const h = element.height * scaleY;
    ctx.save();
    ctx.globalAlpha = clamp(numberOr(element.opacity, 1), 0, 1);
    if (element.rotation) {
      ctx.translate(x + w / 2, y + h / 2);
      ctx.rotate((element.rotation * Math.PI) / 180);
      ctx.translate(-(x + w / 2), -(y + h / 2));
    }
    if (element.type === "shape") {
      ctx.fillStyle = element.style?.backgroundColor || "#F4F1EA";
      drawCreativeRoundRect(ctx, x, y, w, h, (element.style?.borderRadius || 0) * scaleX);
      ctx.fill();
    } else if (element.type === "image" && element.src) {
      try {
        const image = await loadCreativeImage(element.src);
        drawCreativeImageCover(ctx, image, x, y, w, h, (element.style?.borderRadius || 0) * scaleX);
      } catch {
        ctx.fillStyle = "#F4F1EA";
        drawCreativeRoundRect(ctx, x, y, w, h, 14 * scaleX);
        ctx.fill();
      }
    } else if (element.type === "palette") {
      const colors = safeArray(element.colors);
      const dot = Math.min(h, 34 * scaleX);
      colors.forEach((color, index) => {
        ctx.fillStyle = color;
        drawCreativeRoundRect(ctx, x + index * (dot + 10 * scaleX), y, dot, dot, dot / 2);
        ctx.fill();
      });
    } else if (element.type === "text") {
      const fontSize = Math.max(8, numberOr(element.style?.fontSize, 24) * scaleY);
      const fontFamily = element.style?.fontFamily || "Georgia";
      const fontWeight = element.style?.fontWeight || "500";
      ctx.fillStyle = element.style?.color || "#181715";
      ctx.textBaseline = "top";
      ctx.font = `${fontWeight} ${fontSize}px "${fontFamily}", Arial, sans-serif`;
      ctx.textAlign = element.style?.textAlign || "left";
      const textX = ctx.textAlign === "center" ? x + w / 2 : ctx.textAlign === "right" ? x + w : x;
      wrapCreativeText(ctx, element.content, textX, y, w, fontSize * 1.18, h);
    }
    ctx.restore();
  }
  return canvas.toDataURL("image/jpeg", 0.92);
}

const CREATIVE_SLIDE_FUNCTION_OPTIONS = [
  { value: "cover", label: "Portada" },
  { value: "moodboard", label: "Mood board" },
  { value: "amenities", label: "Amenidad" },
  { value: "materials", label: "Materiales" },
  { value: "gallery", label: "Galeria" },
  { value: "plan-2d", label: "Plano" },
  { value: "closing", label: "Cierre" },
];

function buildBrochurePhotoPrompt(element, slide) {
  const settings = element?.photoSettings || {};
  const source = findCreativeImageSourceBySrc(element?.src || "");
  const sourceId = source?.id || element?.sourceAssetId || element?.sourceGalleryItemId || "";
  const promptContext = buildPromptContext({
    project: state.project,
    module: "brochureStudio",
    targetOutput: "imageLayer",
    primaryAssetId: sourceId || null,
    selectedAssetIds: [sourceId].filter(Boolean),
    userOptions: {
      ...settings,
      style: settings.style || settings.finish || "photographic",
      light: settings.light || "natural",
      changeRequest: settings.changeRequest || settings.prompt || "",
    },
    userFeedback: settings.changeRequest || settings.prompt || "",
    slide: {
      ...slide,
      slideType: slide?.sectionId || slide?.layout || "brochure",
    },
    layer: element,
  });
  promptContext.visualInventory = buildVisualInventoryFromAnalysis(source?.analysis || source?.metadata?.analysis || null);
  return buildBrochureImageLayerPrompt(promptContext);
}

function findCreativeImageSourceBySrc(src = "") {
  return getCreativeEditorImages().find((image) => image.src === src) || null;
}

class CreativeDeckEditor {
  constructor(mountEl, initialState) {
    this.mountEl = mountEl;
    this.state = cloneCreativeEditorValue(initialState, {});
    this.history = [cloneCreativeEditorValue(this.state, {})];
    this.historyIndex = 0;
    this.dragSession = null;
    this.importMode = "image";
    this.boundClick = this.handleClick.bind(this);
    this.boundInput = this.handleInput.bind(this);
    this.boundChange = this.handleChange.bind(this);
    this.boundMouseDown = this.handleMouseDown.bind(this);
    this.boundMouseMove = this.handleMouseMove.bind(this);
    this.boundMouseUp = this.handleMouseUp.bind(this);
  }

  mount() {
    this.mountEl.innerHTML = `<section class="creative-editor-shell"></section>`;
    this.root = this.mountEl.querySelector(".creative-editor-shell");
    this.root.addEventListener("click", this.boundClick);
    this.root.addEventListener("input", this.boundInput);
    this.root.addEventListener("change", this.boundChange);
    this.root.addEventListener("mousedown", this.boundMouseDown);
    document.addEventListener("mousemove", this.boundMouseMove);
    document.addEventListener("mouseup", this.boundMouseUp);
    this.render();
    this.sync();
  }

  unmount() {
    if (this.root) {
      this.root.removeEventListener("click", this.boundClick);
      this.root.removeEventListener("input", this.boundInput);
      this.root.removeEventListener("change", this.boundChange);
      this.root.removeEventListener("mousedown", this.boundMouseDown);
    }
    document.removeEventListener("mousemove", this.boundMouseMove);
    document.removeEventListener("mouseup", this.boundMouseUp);
    this.mountEl.innerHTML = "";
  }

  serialize() {
    return cloneCreativeEditorValue(this.state, {});
  }

  activeSlide() {
    return this.state.slides.find((slide) => slide.id === this.state.activeSlideId) || this.state.slides[0] || null;
  }

  activeElement() {
    const slide = this.activeSlide();
    return slide?.elements.find((element) => element.id === this.state.activeElementId) || null;
  }

  commit() {
    const snapshot = cloneCreativeEditorValue(this.state, {});
    this.history = this.history.slice(0, this.historyIndex + 1);
    this.history.push(snapshot);
    this.history = this.history.slice(-40);
    this.historyIndex = this.history.length - 1;
  }

  mutate(callback, options = {}) {
    callback(this.state);
    if (options.history !== false) this.commit();
    this.render();
    this.sync();
  }

  sync() {
    syncCreativeDeckEditorState(this.serialize());
  }

  render() {
    if (!this.root) return;
    const slide = this.activeSlide();
    const element = this.activeElement();
    const scale = this.state.zoom / 100;
    this.root.innerHTML = `
      <header class="creative-editor-head">
        <div class="creative-editor-brand">
          <strong>Brochure Studio</strong>
          <span class="pro-badge">PRO</span>
        </div>
        <div class="creative-project-title">
          <span>Proyecto</span>
          <input type="text" class="creative-title-input" data-ed-deck-title value="${escapeHtml(this.state.title || "")}" aria-label="Titulo del deck">
        </div>
        <div class="creative-editor-actions">
          <button type="button" class="button button-secondary" data-ed-action="preview">Vista previa</button>
          <button type="button" class="button button-primary" data-ed-action="render-deck">Generar PPT renderizado</button>
          <button type="button" class="button button-secondary" data-ed-action="export-pdf">Exportar PDF</button>
          <button type="button" class="button button-secondary" data-ed-action="export-ppt">Exportar PPTX</button>
        </div>
      </header>
      <section class="creative-editor-workspace">
        <aside class="creative-slide-rail">
          <div class="rail-head">
            <span class="eyebrow">Diapositivas</span>
            <button type="button" class="icon-button" data-ed-action="add-slide" title="Nueva diapositiva">+</button>
          </div>
          <div class="creative-slide-list">
            ${safeArray(this.state.slides).map((item, index) => this.renderSlideThumb(item, index)).join("")}
          </div>
        </aside>
        <main class="creative-canvas-column">
          ${this.renderToolbar()}
          <div class="creative-canvas-stage">
            <div class="creative-canvas-frame" style="width:${CREATIVE_EDITOR_SIZE.width * scale}px;height:${CREATIVE_EDITOR_SIZE.height * scale}px;">
              ${slide ? this.renderCanvas(slide, scale) : this.renderEmptyCanvas()}
            </div>
          </div>
          <footer class="creative-editor-footer">
            <span>${safeArray(slide?.elements).length} capas editables</span>
            <span>Zoom ${Math.round(this.state.zoom)}%</span>
          </footer>
          ${this.renderPhotoInstanceWorkbench(slide, element)}
        </main>
        <aside class="creative-props-panel">
          ${this.renderInspector(slide, element)}
          ${this.renderLayers(slide)}
        </aside>
      </section>
      <input type="file" class="hidden" data-ed-file accept="image/*,.pdf">
    `;
  }

  renderSlideThumb(slide, index) {
    const isActive = slide.id === this.state.activeSlideId;
    const previewImage = safeArray(slide.elements).find((element) => element.type === "image" && element.src)?.src || "";
    const roleValue = slide.sectionId || "gallery";
    return `
      <article class="creative-slide-thumb ${isActive ? "active" : ""}" data-ed-slide="${escapeHtml(slide.id)}">
        <div class="creative-thumb-preview">
          ${previewImage ? `<img src="${escapeHtml(previewImage)}" alt="">` : `<span>${index + 1}</span>`}
        </div>
        <div>
          <strong>${escapeHtml(slide.name || `Diapositiva ${index + 1}`)}</strong>
          <small>${slide.elements.length} capas · 16:9</small>
          <select data-ed-slide-role="${escapeHtml(slide.id)}" aria-label="Funcion de diapositiva">
            ${CREATIVE_SLIDE_FUNCTION_OPTIONS.map((option) => `<option value="${escapeHtml(option.value)}" ${roleValue === option.value ? "selected" : ""}>${escapeHtml(option.label)}</option>`).join("")}
          </select>
        </div>
        <div class="thumb-actions">
          <button type="button" data-ed-action="duplicate-slide" data-ed-id="${escapeHtml(slide.id)}">Duplicar</button>
          <button type="button" data-ed-action="delete-slide" data-ed-id="${escapeHtml(slide.id)}">Eliminar</button>
        </div>
      </article>
    `;
  }

  renderToolbar() {
    const palette = getCreativeEditorPalette();
    const element = this.activeElement();
    const style = element?.style || {};
    const activeTab = this.state.activeTab || "home";
    return `
      <div class="creative-editor-toolbar">
        <div class="tool-group nav-tools">
          ${BROCHURE_EDITOR_TABS.map((tab) => `<button type="button" class="${activeTab === tab.id ? "active" : ""}" data-ed-action="tab-${escapeHtml(tab.id)}">${escapeHtml(tab.label)}</button>`).join("")}
        </div>
        <div class="tool-group">
          <button type="button" data-ed-action="undo">↶</button>
          <button type="button" data-ed-action="redo">↷</button>
        </div>
        <div class="tool-group font-tools">
          <select data-ed-prop="style.fontFamily" ${element?.type !== "text" ? "disabled" : ""}>
            ${CREATIVE_EDITOR_FONTS.map((font) => `<option value="${escapeHtml(font)}" ${style.fontFamily === font ? "selected" : ""}>${escapeHtml(font)}</option>`).join("")}
          </select>
          <input type="number" min="8" max="96" data-ed-prop="style.fontSize" value="${numberOr(style.fontSize, 36)}" ${element?.type !== "text" ? "disabled" : ""}>
          <button type="button" data-ed-action="toggle-bold" class="${style.fontWeight === "700" ? "active" : ""}" ${element?.type !== "text" ? "disabled" : ""}>B</button>
          <button type="button" data-ed-action="toggle-italic" class="${style.fontStyle === "italic" ? "active" : ""}" ${element?.type !== "text" ? "disabled" : ""}>I</button>
          <button type="button" data-ed-action="toggle-underline" class="${style.textDecoration === "underline" ? "active" : ""}" ${element?.type !== "text" ? "disabled" : ""}>U</button>
          <input type="color" data-ed-prop="${element?.type === "shape" ? "style.backgroundColor" : "style.color"}" value="${escapeHtml(element?.type === "shape" ? (style.backgroundColor || "#F4F1EA") : (style.color || "#181715"))}" ${!element ? "disabled" : ""}>
        </div>
        <div class="tool-group reference-tools">
          <button type="button" data-ed-action="add-shape">Forma</button>
          <button type="button" data-ed-action="add-line">Linea</button>
          <button type="button" data-ed-action="import-image">Subir referencia</button>
          <input type="url" data-ed-url-input placeholder="URL publica de imagen">
          <button type="button" data-ed-action="insert-url">Insertar</button>
          <button type="button" data-ed-action="background-url">Fondo</button>
        </div>
        <div class="tool-group template-tools">
          <button type="button" data-ed-template="cover">Portada</button>
          <button type="button" data-ed-template="moodboard">Moodboard</button>
          <button type="button" data-ed-template="technical">Tecnica</button>
        </div>
        <div class="tool-group color-tools">
          ${palette.slice(0, 7).map((color) => `<button type="button" class="color-dot" style="background:${escapeHtml(color)}" data-ed-bg="${escapeHtml(color)}" title="${escapeHtml(color)}"></button>`).join("")}
        </div>
        <div class="tool-group zoom-tools">
          <button type="button" data-ed-action="zoom-out">-</button>
          <button type="button" data-ed-action="zoom-in">+</button>
        </div>
      </div>
      ${this.renderBrochureContextualToolbar(element, activeTab)}
      ${this.renderTemplateSlideStrip()}
      ${this.renderSourceImageStrip()}
    `;
  }

  renderBrochureContextualToolbar(element, activeTab = "home") {
    if (activeTab === "insert") return this.renderBrochureInsertToolbar();
    if (activeTab === "layout") return this.renderBrochureLayoutToolbar();
    if (activeTab === "ia") return this.renderBrochureIaToolbar(element);
    return this.renderBrochureHomeToolbar(element);
  }

  renderBrochureHomeToolbar(element) {
    if (!element) {
      return `
        <div class="creative-context-toolbar">
          <span class="eyebrow">Inicio</span>
          <button type="button" data-ed-action="add-text">Agregar titulo</button>
          <button type="button" data-ed-action="add-image">Agregar imagen</button>
          <button type="button" data-ed-action="add-shape">Agregar forma</button>
          <button type="button" data-ed-action="tab-layout">Seleccionar layout</button>
        </div>
      `;
    }
    const imageTools = element.type === "image" ? `
      <button type="button" data-ed-action="object-fit-cover">Cover</button>
      <button type="button" data-ed-action="object-fit-contain">Contain</button>
      <button type="button" data-ed-action="render-selected-photo">Renderizar instancia</button>
      <button type="button" data-ed-action="revert-selected-photo">Usar original</button>
    ` : "";
    const shapeTools = element.type === "shape" ? `
      <button type="button" data-ed-action="add-line">Linea</button>
    ` : "";
    return `
      <div class="creative-context-toolbar">
        <span class="eyebrow">${escapeHtml(element.type)} seleccionado</span>
        ${imageTools}
        ${shapeTools}
        <button type="button" data-ed-action="layer-up">Traer adelante</button>
        <button type="button" data-ed-action="layer-down">Enviar atras</button>
        <button type="button" data-ed-action="layer-front">Al frente</button>
        <button type="button" data-ed-action="layer-back">Al fondo</button>
        <button type="button" data-ed-action="toggle-visible">${element.visible === false ? "Mostrar" : "Ocultar"}</button>
        <button type="button" data-ed-action="toggle-lock">${element.locked ? "Desbloquear" : "Bloquear"}</button>
        <button type="button" data-ed-action="duplicate-element">Duplicar</button>
        <button type="button" data-ed-action="delete-element">Eliminar</button>
      </div>
    `;
  }

  renderBrochureInsertToolbar() {
    return `
      <div class="creative-context-toolbar">
        <span class="eyebrow">Insertar capa</span>
        <button type="button" data-ed-action="add-text">Titulo</button>
        <button type="button" data-ed-action="add-body-text">Texto</button>
        <button type="button" data-ed-action="add-image">Imagen desde Assets/Gallery</button>
        <button type="button" data-ed-action="add-image-frame">Marco de imagen</button>
        <button type="button" data-ed-action="add-shape">Rectangulo</button>
        <button type="button" data-ed-action="add-circle">Circulo</button>
        <button type="button" data-ed-action="add-line">Linea</button>
        <button type="button" data-ed-action="add-separator">Separador</button>
        <button type="button" data-ed-action="add-pill">Pill / Tag</button>
        <button type="button" data-ed-action="add-palette">Paleta</button>
        <button type="button" data-ed-action="background-url">Fondo de imagen</button>
      </div>
    `;
  }

  renderBrochureLayoutToolbar() {
    const slide = this.activeSlide();
    const rawType = slide?.sectionId || "cover";
    const activeType = BROCHURE_SLIDE_TYPES[rawType] ? rawType : "cover";
    return `
      <div class="creative-context-toolbar layout-toolbar">
        <span class="eyebrow">Layout de pagina</span>
        ${Object.entries(BROCHURE_SLIDE_TYPES).map(([type, definition]) => `
          <button type="button" class="${activeType === type ? "active" : ""}" data-ed-layout-type="${escapeHtml(type)}">${escapeHtml(definition.label)}</button>
        `).join("")}
      </div>
      <div class="creative-context-toolbar layout-variant-toolbar">
        ${safeArray(BROCHURE_SLIDE_TYPES[activeType]?.variants || BROCHURE_SLIDE_TYPES.cover.variants).map((variant) => `
          <button type="button" class="${slide?.layout === variant.id ? "active" : ""}" data-ed-layout-type="${escapeHtml(activeType)}" data-ed-layout-variant="${escapeHtml(variant.id)}">
            <strong>${escapeHtml(variant.name)}</strong>
            <small>${escapeHtml(variant.description || "")}</small>
          </button>
        `).join("")}
      </div>
    `;
  }

  renderBrochureIaToolbar(element) {
    return `
      <div class="creative-context-toolbar">
        <span class="eyebrow">IA contextual</span>
        ${element?.type === "image" ? `<button type="button" data-ed-action="render-selected-photo">Renderizar solo esta imagen</button>` : ""}
        <button type="button" data-ed-action="preview">Vista previa</button>
        <button type="button" data-ed-action="render-deck">Generar PPT renderizado</button>
      </div>
    `;
  }

  renderTemplateSlideStrip() {
    const entry = getSelectedLocalTemplateEntry();
    const previews = safeArray(entry?.slidePreviews).slice(0, 16);
    if (!previews.length) return "";
    const activeLayout = this.activeSlide()?.layout || "";
    return `
      <div class="creative-template-slide-strip" aria-label="Hojas de la plantilla PPT">
        <div class="creative-strip-head">
          <span class="eyebrow">Hojas de plantilla</span>
          <strong>${escapeHtml(entry.label || "Plantilla seleccionada")}</strong>
        </div>
        <div class="creative-template-slide-list">
          ${previews.map((preview, index) => {
            const slideNumber = Number(preview.slide || preview.page || index + 1);
            const layoutId = `tpl-page-${slideNumber}`;
            const previewSrc = `${preview.path || entry.thumbnail || ""}${preview.path ? "?v=2" : ""}`;
            return `
              <button type="button" class="creative-template-slide-button ${activeLayout === layoutId ? "active" : ""}" data-ed-template-slide="${escapeHtml(layoutId)}" title="Usar hoja ${slideNumber}">
                ${previewSrc ? `<img src="${escapeHtml(previewSrc)}" alt="">` : `<span>${slideNumber}</span>`}
                <small>${slideNumber}</small>
              </button>
            `;
          }).join("")}
        </div>
      </div>
    `;
  }

  renderSourceImageStrip() {
    const images = getCreativeEditorImages().slice(0, 12);
    if (!images.length) return "";
    return `
      <div class="creative-asset-source-strip" aria-label="Imagenes del proyecto">
        <div class="creative-strip-head">
          <span class="eyebrow">Fotos / renders del proyecto</span>
          <strong>${images.length} fuente${images.length === 1 ? "" : "s"} listas</strong>
        </div>
        <div class="creative-asset-source-list">
          ${images.map((image) => `
            <button type="button" class="creative-asset-pill" data-ed-asset-src="${escapeHtml(image.src)}" title="${escapeHtml(image.name)}">
              <img src="${escapeHtml(image.src)}" alt="">
              <span>${escapeHtml(image.name)}</span>
            </button>
          `).join("")}
        </div>
      </div>
    `;
  }

  renderPhotoInstanceWorkbench(slide, element) {
    const images = getCreativeEditorImages().slice(0, 14);
    const isImage = element?.type === "image";
    const imageLayers = safeArray(slide?.elements).filter((item) => item.type === "image");
    const activeImage = isImage ? element : imageLayers[0] || null;
    const settings = activeImage?.photoSettings || {};
    const originalUrl = getBrochureImageLayerOriginalUrl(activeImage);
    const renderedUrl = getBrochureImageLayerRenderedUrl(activeImage);
    return `
      <section class="creative-photo-instance-workbench">
        <div class="creative-photo-head">
          <div>
            <span class="eyebrow">Editor de imagen por instancia</span>
            <strong>${activeImage ? escapeHtml(activeImage.name || "Imagen seleccionada") : "No hay imagenes en esta diapositiva"}</strong>
            <p>${activeImage ? "Esta edicion afecta solo este cuadro de imagen, no el asset original ni otras copias." : "Inserta una imagen o elige un layout con slots de imagen."}</p>
          </div>
          <div class="instance-badge">Slot ${escapeHtml(activeImage?.slotInstanceId || "")}</div>
        </div>
        ${activeImage ? `
        <div class="image-instance-layout">
          <div class="image-instance-preview">
            <span>Original</span>
            ${originalUrl ? `<img src="${escapeHtml(originalUrl)}" alt="">` : `<div class="empty-image-slot">Sin imagen asignada</div>`}
          </div>
          <div class="image-instance-preview">
            <span>Render de esta instancia</span>
            ${renderedUrl ? `<img src="${escapeHtml(renderedUrl)}" alt="">` : `<div class="empty-image-slot">Aun no renderizado</div>`}
          </div>
        </div>
        <div class="image-instance-actions">
          <button type="button" class="button button-secondary" data-ed-action="revert-selected-photo">Usar sin renderizar</button>
          <button type="button" class="button button-primary" data-ed-action="render-selected-photo">Renderizar esta imagen</button>
          <button type="button" class="button button-secondary" data-ed-action="render-selected-photo">Regenerar esta instancia</button>
        </div>
        <div class="image-instance-controls">
          <label>Estilo
            <select data-ed-prop="photoSettings.style">
              ${[["photographic", "Fotografia real"], ["three-dimensional", "Imagen 3D premium"], ["linear-drawing", "Render lineal"], ["mixed-media", "Mixto editorial"]].map(([value, label]) => `<option value="${value}" ${settings.style === value ? "selected" : ""}>${label}</option>`).join("")}
            </select>
          </label>
          <label>Fidelidad
            <select data-ed-prop="photoSettings.fidelity">
              ${[["strict", "Estricta"], ["balanced", "Balanceada"], ["creative", "Creativa controlada"]].map(([value, label]) => `<option value="${value}" ${settings.fidelity === value ? "selected" : ""}>${label}</option>`).join("")}
            </select>
          </label>
          <label>Luz
            <select data-ed-prop="photoSettings.light">
              ${[["natural", "Natural"], ["warm-ambient", "Ambiental calida"], ["golden-hour", "Golden hour"], ["night", "Noche"]].map(([value, label]) => `<option value="${value}" ${settings.light === value ? "selected" : ""}>${label}</option>`).join("")}
            </select>
          </label>
          <label>Cambios puntuales
            <textarea rows="3" data-ed-prop="photoSettings.changeRequest" placeholder="Ej: mejorar luz y textura sin cambiar cama, puerta ni composicion.">${escapeHtml(settings.changeRequest || settings.prompt || "")}</textarea>
          </label>
        </div>` : ""}
        <div class="creative-photo-workbench-grid">
          <div class="creative-photo-strip">
            ${images.length ? images.map((image) => `
              <button type="button" class="creative-photo-chip ${activeImage && activeImage.src === image.src ? "active" : ""}" data-ed-photo-src="${escapeHtml(image.src)}" title="${escapeHtml(image.name)}">
                <img src="${escapeHtml(image.src)}" alt="">
                <span>${escapeHtml(image.name)}</span>
                <small>${escapeHtml(image.sourceType || "project")}</small>
              </button>
            `).join("") : `<div class="empty-state compact-empty"><strong>Sin fotos</strong><span>Selecciona imagenes desde Assets o Gallery en el paso 1.</span></div>`}
          </div>
        </div>
      </section>
    `;
  }

  renderCanvas(slide, scale) {
    const background = slide.background || { type: "color", value: "#FFFFFF" };
    const bgStyle = background.type === "image" && background.value
      ? `background:url(&quot;${escapeHtml(cssUrl(background.value))}&quot;) center / cover no-repeat;`
      : `background:${escapeHtml(background.value || "#FFFFFF")};`;
    const layers = safeArray(slide.elements).filter((element) => element.visible !== false).sort((a, b) => numberOr(a.zIndex, 0) - numberOr(b.zIndex, 0));
    return `
      <div class="creative-canvas" style="width:${CREATIVE_EDITOR_SIZE.width}px;height:${CREATIVE_EDITOR_SIZE.height}px;transform:scale(${scale});${bgStyle}">
        ${layers.map((element) => this.renderCanvasElement(element)).join("")}
        ${layers.length ? "" : `
          <div class="creative-empty-canvas">
            <strong>Selecciona una plantilla o agrega tu primer elemento</strong>
            <div>
              <button type="button" data-ed-action="add-text">Agregar texto</button>
              <button type="button" data-ed-action="add-image">Agregar imagen</button>
              <button type="button" data-ed-template="cover">Usar plantilla</button>
            </div>
          </div>
        `}
      </div>
    `;
  }

  renderEmptyCanvas() {
    return `<div class="creative-empty-canvas"><strong>Crea una diapositiva para comenzar.</strong><button type="button" data-ed-action="add-slide">Nueva diapositiva</button></div>`;
  }

  renderCanvasElement(element) {
    const selected = element.id === this.state.activeElementId;
    const style = [
      `left:${element.x}px`,
      `top:${element.y}px`,
      `width:${element.width}px`,
      `height:${element.height}px`,
      `z-index:${element.zIndex}`,
      `opacity:${element.opacity}`,
      `transform:rotate(${element.rotation || 0}deg)`,
    ].join(";");
    const base = `class="creative-layer creative-layer-${element.type} ${selected ? "selected" : ""} ${element.locked ? "locked" : ""}" data-ed-element-id="${escapeHtml(element.id)}" style="${style}"`;
    const handles = selected && !element.locked ? `
      <span class="resize-handle nw" data-ed-resize="nw"></span>
      <span class="resize-handle ne" data-ed-resize="ne"></span>
      <span class="resize-handle sw" data-ed-resize="sw"></span>
      <span class="resize-handle se" data-ed-resize="se"></span>
    ` : "";
    if (element.type === "text") {
      const textStyle = `font-family:${escapeHtml(element.style.fontFamily || "Georgia")};font-size:${numberOr(element.style.fontSize, 24)}px;font-weight:${escapeHtml(element.style.fontWeight || "500")};font-style:${escapeHtml(element.style.fontStyle || "normal")};text-decoration:${escapeHtml(element.style.textDecoration || "none")};color:${escapeHtml(element.style.color || "#181715")};text-align:${escapeHtml(element.style.textAlign || "left")};line-height:${element.style.lineHeight || 1.15};letter-spacing:${numberOr(element.style.letterSpacing, 0)}px;`;
      return `<div ${base}><div class="creative-text-content" contenteditable="true" data-ed-text-content style="${textStyle}">${escapeHtml(element.content || "").replace(/\n/g, "<br>")}</div>${handles}</div>`;
    }
    if (element.type === "image") {
      const radius = numberOr(element.style.borderRadius, 18);
      const content = element.src
        ? `<img src="${escapeHtml(element.src)}" alt="" style="border-radius:${radius}px;object-fit:${escapeHtml(element.objectFit || "cover")};">`
        : `<div class="creative-image-placeholder"><strong>Imagen</strong><span>Inserta referencia</span></div>`;
      return `<div ${base}>${content}${handles}</div>`;
    }
    if (element.type === "palette") {
      return `<div ${base}><div class="brochure-palette-row">${safeArray(element.colors).map((color) => `<span class="palette-dot" style="background:${escapeHtml(color)}"></span>`).join("")}</div>${handles}</div>`;
    }
    return `<div ${base}><div class="creative-shape-fill" style="background:${escapeHtml(element.style.backgroundColor || "#F4F1EA")};border:${numberOr(element.style.borderWidth, 0)}px solid ${escapeHtml(element.style.borderColor || "transparent")};border-radius:${numberOr(element.style.borderRadius, 12)}px;"></div>${handles}</div>`;
  }

  renderInspector(slide, element) {
    if (!slide) return `<div class="inspector-section"><strong>Sin diapositiva</strong></div>`;
    if (!element) {
      return `
        <section class="inspector-section">
          <span class="eyebrow">Propiedades de slide</span>
          <label>Nombre<input type="text" data-ed-slide-prop="name" value="${escapeHtml(slide.name || "")}"></label>
          <label>Fondo<input type="color" data-ed-slide-bg value="${escapeHtml(slide.background?.type === "color" ? slide.background.value : "#FFFFFF")}"></label>
          <p class="microcopy">Selecciona una capa para editar texto, imagen, forma, posicion y profundidad.</p>
        </section>
        ${this.renderAssetPicker()}
      `;
    }
    const style = element.style || {};
    return `
      <section class="inspector-section">
        <span class="eyebrow">Seleccion</span>
        <label>Nombre<input type="text" data-ed-prop="name" value="${escapeHtml(element.name || "")}"></label>
        ${element.type === "text" ? `
          <label>Texto<textarea data-ed-prop="content" rows="4">${escapeHtml(element.content || "")}</textarea></label>
          <label>Fuente<select data-ed-prop="style.fontFamily">${CREATIVE_EDITOR_FONTS.map((font) => `<option value="${escapeHtml(font)}" ${style.fontFamily === font ? "selected" : ""}>${escapeHtml(font)}</option>`).join("")}</select></label>
          <div class="two-col">
            <label>Tamano<input type="number" min="8" max="96" data-ed-prop="style.fontSize" value="${numberOr(style.fontSize, 24)}"></label>
            <label>Peso<select data-ed-prop="style.fontWeight"><option value="400" ${style.fontWeight === "400" ? "selected" : ""}>Regular</option><option value="600" ${style.fontWeight === "600" ? "selected" : ""}>Semibold</option><option value="700" ${style.fontWeight === "700" ? "selected" : ""}>Bold</option></select></label>
          </div>
          <div class="two-col">
            <label>Color<input type="color" data-ed-prop="style.color" value="${escapeHtml(style.color || "#181715")}"></label>
            <label>Alinear<select data-ed-prop="style.textAlign"><option value="left" ${style.textAlign === "left" ? "selected" : ""}>Izq.</option><option value="center" ${style.textAlign === "center" ? "selected" : ""}>Centro</option><option value="right" ${style.textAlign === "right" ? "selected" : ""}>Der.</option></select></label>
          </div>
        ` : ""}
        ${element.type === "shape" ? `
          <div class="two-col">
            <label>Color<input type="color" data-ed-prop="style.backgroundColor" value="${escapeHtml(style.backgroundColor || "#F4F1EA")}"></label>
            <label>Radio<input type="number" min="0" max="80" data-ed-prop="style.borderRadius" value="${numberOr(style.borderRadius, 12)}"></label>
          </div>
        ` : ""}
        ${element.type === "image" ? `
          <label>Imagen del proyecto
            <select data-ed-prop="src">
              <option value="${escapeHtml(element.src || "")}">Actual</option>
              ${getCreativeEditorImages().map((image) => `<option value="${escapeHtml(image.src)}" ${element.src === image.src ? "selected" : ""}>${escapeHtml(image.name)}</option>`).join("")}
            </select>
          </label>
          <label>URL / imagen<input type="text" data-ed-prop="src" value="${escapeHtml(element.src || "")}"></label>
          <div class="two-col">
            <label>Radio<input type="number" min="0" max="80" data-ed-prop="style.borderRadius" value="${numberOr(style.borderRadius, 18)}"></label>
            <label>Filtro<select data-ed-prop="photoSettings.finish"><option value="natural" ${element.photoSettings?.finish === "natural" ? "selected" : ""}>Natural</option><option value="editorial" ${element.photoSettings?.finish === "editorial" ? "selected" : ""}>Editorial</option><option value="warm" ${element.photoSettings?.finish === "warm" ? "selected" : ""}>Calido</option><option value="crisp" ${element.photoSettings?.finish === "crisp" ? "selected" : ""}>Nitido</option></select></label>
          </div>
          <label>Ajuste individual<textarea rows="3" data-ed-prop="photoSettings.prompt" placeholder="Cambios solo para esta copia de la imagen...">${escapeHtml(element.photoSettings?.prompt || "")}</textarea></label>
          <label>Modo moodboard<select data-ed-prop="photoSettings.moodboardLayout"><option value="">Ninguno</option><option value="object-flatlay" ${element.photoSettings?.moodboardLayout === "object-flatlay" ? "selected" : ""}>Flatlay</option><option value="texture-board" ${element.photoSettings?.moodboardLayout === "texture-board" ? "selected" : ""}>Texturas</option><option value="editorial-collage" ${element.photoSettings?.moodboardLayout === "editorial-collage" ? "selected" : ""}>Collage editorial</option></select></label>
        ` : ""}
        <div class="two-col">
          <label>X<input type="number" data-ed-prop="x" value="${Math.round(element.x)}"></label>
          <label>Y<input type="number" data-ed-prop="y" value="${Math.round(element.y)}"></label>
          <label>Ancho<input type="number" min="20" data-ed-prop="width" value="${Math.round(element.width)}"></label>
          <label>Alto<input type="number" min="20" data-ed-prop="height" value="${Math.round(element.height)}"></label>
        </div>
        <label>Opacidad<input type="range" min="0.05" max="1" step="0.05" data-ed-prop="opacity" value="${element.opacity}"></label>
        <div class="tool-group full">
          <button type="button" data-ed-action="layer-up">Traer adelante</button>
          <button type="button" data-ed-action="layer-down">Enviar atras</button>
          <button type="button" data-ed-action="delete-element">Eliminar</button>
        </div>
      </section>
      ${this.renderAssetPicker()}
    `;
  }

  renderAssetPicker() {
    const images = getCreativeEditorImages().slice(0, 6);
    return `
      <section class="inspector-section">
        <span class="eyebrow">Assets del flujo</span>
        <div class="asset-palette">
          ${images.length ? images.map((image) => `
            <button type="button" class="asset-chip" data-ed-asset-src="${escapeHtml(image.src)}">
              <img src="${escapeHtml(image.src)}" alt="">
              <span>${escapeHtml(image.name)}</span>
            </button>
          `).join("") : `<p class="microcopy">Sube imagenes en Insumos o importa una referencia local.</p>`}
        </div>
      </section>
    `;
  }

  renderLayers(slide) {
    const layers = safeArray(slide?.elements).slice().sort((a, b) => numberOr(b.zIndex, 0) - numberOr(a.zIndex, 0));
    return `
      <section class="inspector-section layer-list-panel">
        <span class="eyebrow">Capas</span>
        ${layers.map((element) => `
          <button type="button" class="layer-row ${element.id === this.state.activeElementId ? "active" : ""}" data-ed-layer-id="${escapeHtml(element.id)}">
            <span>${escapeHtml(element.name || element.type)}</span>
            <small>${escapeHtml(element.type)} · z${element.zIndex}</small>
          </button>
        `).join("") || `<p class="microcopy">No hay capas en esta diapositiva.</p>`}
      </section>
    `;
  }

  handleClick(event) {
    const slideButton = event.target.closest("[data-ed-slide]");
    if (slideButton && !event.target.closest("button")) {
      this.mutate((draft) => {
        draft.activeSlideId = slideButton.dataset.edSlide;
        draft.activeElementId = draft.slides.find((slide) => slide.id === draft.activeSlideId)?.elements?.[0]?.id || null;
      }, { history: false });
      return;
    }

    const layerButton = event.target.closest("[data-ed-layer-id]");
    if (layerButton) {
      this.mutate((draft) => { draft.activeElementId = layerButton.dataset.edLayerId; }, { history: false });
      return;
    }

    const photoSourceButton = event.target.closest("[data-ed-photo-src]");
    if (photoSourceButton) {
      this.applyPhotoSource(photoSourceButton.dataset.edPhotoSrc || "");
      return;
    }

    const assetButton = event.target.closest("[data-ed-asset-src]");
    if (assetButton) {
      this.addImage(assetButton.dataset.edAssetSrc);
      return;
    }

    const bgButton = event.target.closest("[data-ed-bg]");
    if (bgButton) {
      this.setSlideBackground({ type: "color", value: bgButton.dataset.edBg });
      return;
    }

    const templateButton = event.target.closest("[data-ed-template]");
    if (templateButton) {
      this.applyTemplate(templateButton.dataset.edTemplate);
      return;
    }

    const templateSlideButton = event.target.closest("[data-ed-template-slide]");
    if (templateSlideButton) {
      this.applyLocalTemplateSlide(templateSlideButton.dataset.edTemplateSlide);
      return;
    }

    const layoutVariantButton = event.target.closest("[data-ed-layout-variant]");
    if (layoutVariantButton) {
      this.applyBrochureLayoutVariant(layoutVariantButton.dataset.edLayoutType || "cover", layoutVariantButton.dataset.edLayoutVariant || "");
      return;
    }

    const layoutTypeButton = event.target.closest("[data-ed-layout-type]");
    if (layoutTypeButton && !layoutTypeButton.dataset.edLayoutVariant) {
      this.setActiveTab("layout");
      this.applyBrochureLayoutType(layoutTypeButton.dataset.edLayoutType || "cover");
      return;
    }

    const actionButton = event.target.closest("[data-ed-action]");
    if (!actionButton) return;
    this.handleAction(actionButton.dataset.edAction, actionButton.dataset.edId || "");
  }

  handleAction(action, id = "") {
    if (action.startsWith("tab-")) return this.setActiveTab(action.replace("tab-", ""));
    if (action === "add-slide") return this.addSlide();
    if (action === "duplicate-slide") return this.duplicateSlide(id);
    if (action === "delete-slide") return this.deleteSlide(id);
    if (action === "add-text") return this.addElement(INSERTABLE_OBJECTS.title.type, INSERTABLE_OBJECTS.title);
    if (action === "add-body-text") return this.addElement(INSERTABLE_OBJECTS.text.type, INSERTABLE_OBJECTS.text);
    if (action === "add-image") return this.addImage(getCreativeEditorImages()[0]?.src || "");
    if (action === "add-image-frame") return this.addElement(INSERTABLE_OBJECTS.imageFrame.type, INSERTABLE_OBJECTS.imageFrame);
    if (action === "add-shape") return this.addElement(INSERTABLE_OBJECTS.rectangle.type, INSERTABLE_OBJECTS.rectangle);
    if (action === "add-circle") return this.addElement(INSERTABLE_OBJECTS.circle.type, INSERTABLE_OBJECTS.circle);
    if (action === "add-line") return this.addElement(INSERTABLE_OBJECTS.line.type, INSERTABLE_OBJECTS.line);
    if (action === "add-separator") return this.addElement(INSERTABLE_OBJECTS.divider.type, INSERTABLE_OBJECTS.divider);
    if (action === "add-pill") return this.addElement(INSERTABLE_OBJECTS.pill.type, INSERTABLE_OBJECTS.pill);
    if (action === "add-palette") return this.addElement(INSERTABLE_OBJECTS.palette.type, { ...INSERTABLE_OBJECTS.palette, colors: getCreativeEditorPalette().slice(0, 5) });
    if (action === "delete-element") return this.deleteActiveElement();
    if (action === "duplicate-element") return this.duplicateActiveElement();
    if (action === "layer-up") return this.shiftLayer(1);
    if (action === "layer-down") return this.shiftLayer(-1);
    if (action === "layer-front") return this.moveLayerToFront();
    if (action === "layer-back") return this.moveLayerToBack();
    if (action === "toggle-visible") return this.toggleActiveElementFlag("visible");
    if (action === "toggle-lock") return this.toggleActiveElementFlag("locked");
    if (action === "object-fit-cover") return this.updateActiveElement("objectFit", "cover");
    if (action === "object-fit-contain") return this.updateActiveElement("objectFit", "contain");
    if (action === "revert-selected-photo") return this.revertActivePhotoInstance();
    if (action === "toggle-bold") return this.toggleTextStyle("fontWeight", "700", "500");
    if (action === "toggle-italic") return this.toggleTextStyle("fontStyle", "italic", "normal");
    if (action === "toggle-underline") return this.toggleTextStyle("textDecoration", "underline", "none");
    if (action === "zoom-in") return this.setZoom(this.state.zoom + 8);
    if (action === "zoom-out") return this.setZoom(this.state.zoom - 8);
    if (action === "undo") return this.undo();
    if (action === "redo") return this.redo();
    if (action === "import-image") {
      this.importMode = "image";
      this.root.querySelector("[data-ed-file]")?.click();
      return null;
    }
    if (action === "insert-url" || action === "background-url") {
      const input = this.root.querySelector("[data-ed-url-input]");
      const value = input?.value?.trim();
      if (!value) return null;
      if (action === "background-url") this.setSlideBackground({ type: "image", value });
      else this.addImage(value);
      input.value = "";
      return null;
    }
    if (action === "export-pdf") return this.export("pdf");
    if (action === "export-ppt") return this.export("ppt");
    if (action === "export-images") return this.export("images");
    if (action === "render-selected-photo") return this.renderActivePhotoInstance();
    if (action === "render-deck") return prepareBrochureResult("rendered");
    if (action === "preview") {
      return prepareBrochureResult("preview");
    }
    return null;
  }

  handleInput(event) {
    const titleInput = event.target.closest("[data-ed-deck-title]");
    if (titleInput) {
      this.state.title = titleInput.value;
      this.sync();
      return;
    }
    const textContent = event.target.closest("[data-ed-text-content]");
    if (textContent) {
      const elementId = textContent.closest("[data-ed-element-id]")?.dataset.edElementId;
      const element = this.activeSlide()?.elements.find((item) => item.id === elementId);
      if (element) {
        element.content = textContent.innerText;
        this.sync();
      }
      return;
    }
    const propInput = event.target.closest("[data-ed-prop]");
    if (propInput) this.updateActiveElement(propInput.dataset.edProp, propInput.value);
  }

  handleChange(event) {
    const slideRole = event.target.closest("[data-ed-slide-role]");
    if (slideRole) {
      const slideId = slideRole.dataset.edSlideRole;
      const role = slideRole.value || "gallery";
      this.mutate((draft) => {
        const slide = draft.slides.find((item) => item.id === slideId);
        if (!slide) return;
        slide.sectionId = role;
        const option = CREATIVE_SLIDE_FUNCTION_OPTIONS.find((item) => item.value === role);
        slide.name = option?.label || slide.name;
        const mappedType = BROCHURE_SLIDE_TYPES[role] ? role : role === "plan-2d" ? "technical" : role === "amenities" || role === "materials" ? "gallery" : role;
        if (BROCHURE_SLIDE_TYPES[mappedType]) {
          const variant = BROCHURE_SLIDE_TYPES[mappedType].variants[0];
          const next = createSlideFromVariant(mappedType, variant.id, slide);
          Object.assign(slide, next);
          draft.activeSlideId = slide.id;
          draft.activeElementId = slide.elements.find((element) => element.type === "text")?.id || slide.elements[0]?.id || null;
        }
      });
      return;
    }
    const slideName = event.target.closest("[data-ed-slide-prop]");
    if (slideName) {
      this.mutate((draft) => {
        const slide = this.activeSlide();
        if (slide) slide.name = slideName.value;
      });
      return;
    }
    const slideBg = event.target.closest("[data-ed-slide-bg]");
    if (slideBg) {
      this.setSlideBackground({ type: "color", value: slideBg.value });
      return;
    }
    const propInput = event.target.closest("[data-ed-prop]");
    if (propInput) {
      this.updateActiveElement(propInput.dataset.edProp, propInput.value);
      return;
    }
    const fileInput = event.target.closest("[data-ed-file]");
    if (!fileInput?.files?.length) return;
    const file = fileInput.files[0];
    if (!file.type.startsWith("image/")) {
      toast("El editor inserta imagenes. Los PDFs siguen disponibles como soporte del flujo.", "warn");
      fileInput.value = "";
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      this.addImage(String(reader.result || ""));
      fileInput.value = "";
    };
    reader.readAsDataURL(file);
  }

  handleMouseDown(event) {
    const layer = event.target.closest("[data-ed-element-id]");
    if (!layer) return;
    const elementId = layer.dataset.edElementId;
    const element = this.activeSlide()?.elements.find((item) => item.id === elementId);
    if (!element) return;
    this.state.activeElementId = elementId;
    if (element.locked) {
      this.render();
      return;
    }
    if (event.target.closest("[data-ed-text-content]")) {
      this.render();
      return;
    }
    const handle = event.target.closest("[data-ed-resize]");
    this.dragSession = {
      mode: handle ? "resize" : "move",
      handle: handle?.dataset.edResize || "",
      startX: event.clientX,
      startY: event.clientY,
      original: { ...element },
    };
    event.preventDefault();
    this.render();
  }

  handleMouseMove(event) {
    if (!this.dragSession) return;
    const element = this.activeElement();
    if (!element) return;
    const scale = this.state.zoom / 100;
    const dx = (event.clientX - this.dragSession.startX) / scale;
    const dy = (event.clientY - this.dragSession.startY) / scale;
    const original = this.dragSession.original;
    if (this.dragSession.mode === "move") {
      element.x = clamp(original.x + dx, -element.width + 20, CREATIVE_EDITOR_SIZE.width - 20);
      element.y = clamp(original.y + dy, -element.height + 20, CREATIVE_EDITOR_SIZE.height - 20);
    } else {
      const handle = this.dragSession.handle;
      if (handle.includes("e")) element.width = Math.max(20, original.width + dx);
      if (handle.includes("s")) element.height = Math.max(20, original.height + dy);
      if (handle.includes("w")) {
        element.x = original.x + dx;
        element.width = Math.max(20, original.width - dx);
      }
      if (handle.includes("n")) {
        element.y = original.y + dy;
        element.height = Math.max(20, original.height - dy);
      }
    }
    this.render();
    this.sync();
  }

  handleMouseUp() {
    if (this.dragSession) {
      this.dragSession = null;
      this.commit();
      this.sync();
    }
  }

  setActiveTab(tabId) {
    this.mutate((draft) => {
      draft.activeTab = BROCHURE_EDITOR_TABS.some((tab) => tab.id === tabId) ? tabId : "home";
    }, { history: false });
  }

  applyBrochureLayoutType(slideType) {
    const definition = BROCHURE_SLIDE_TYPES[slideType] || BROCHURE_SLIDE_TYPES.cover;
    const variant = definition.variants[0];
    this.applyBrochureLayoutVariant(slideType, variant.id);
  }

  applyBrochureLayoutVariant(slideType, variantId) {
    this.mutate((draft) => {
      const current = this.activeSlide();
      if (!current) return;
      const next = createSlideFromVariant(slideType, variantId, current);
      draft.slides = draft.slides.map((slide) => slide.id === current.id ? next : slide);
      draft.activeSlideId = next.id;
      draft.activeElementId = next.elements.find((element) => element.type === "text")?.id || next.elements[0]?.id || null;
      draft.activeTab = "layout";
    });
  }

  duplicateActiveElement() {
    this.mutate((draft) => {
      const slide = this.activeSlide();
      const element = this.activeElement();
      if (!slide || !element) return;
      const copy = normalizeCreativeElement({
        ...cloneCreativeEditorValue(element, {}),
        id: createCreativeEditorId(element.type || "el"),
        name: `${element.name || "Capa"} copia`,
        x: element.x + 24,
        y: element.y + 24,
        slotInstanceId: element.type === "image" ? createId("slot") : element.slotInstanceId,
      });
      slide.elements.push(copy);
      draft.activeElementId = copy.id;
    });
  }

  moveLayerToFront() {
    this.mutate(() => {
      const slide = this.activeSlide();
      const element = this.activeElement();
      if (!slide || !element) return;
      element.zIndex = Math.max(0, ...slide.elements.map((item) => numberOr(item.zIndex, 0))) + 1;
    });
  }

  moveLayerToBack() {
    this.mutate(() => {
      const slide = this.activeSlide();
      const element = this.activeElement();
      if (!slide || !element) return;
      element.zIndex = Math.min(0, ...slide.elements.map((item) => numberOr(item.zIndex, 0))) - 1;
    });
  }

  toggleActiveElementFlag(flag) {
    this.mutate(() => {
      const element = this.activeElement();
      if (!element) return;
      if (flag === "visible") element.visible = element.visible === false;
      if (flag === "locked") element.locked = !element.locked;
    });
  }

  revertActivePhotoInstance() {
    this.mutate(() => {
      const element = this.activeElement();
      if (!element || element.type !== "image") return;
      element.src = element.originalSrc || element.src;
      element.renderMode = "original";
      element.renderedAssetId = "";
      element.metadata = { ...(element.metadata || {}), renderedGalleryItemId: "" };
    });
    toast("Esta instancia vuelve a usar la imagen original.", "ok");
  }

  addSlide() {
    this.mutate((draft) => {
      const slide = createSlideFromVariant("cover", "cover-editorial-split", {
        id: createCreativeEditorId("slide"),
        name: `Diapositiva ${draft.slides.length + 1}`,
      });
      draft.slides.push(slide);
      draft.activeSlideId = slide.id;
      draft.activeElementId = slide.elements[0]?.id || null;
    });
  }

  duplicateSlide(id) {
    this.mutate((draft) => {
      const source = draft.slides.find((slide) => slide.id === id) || this.activeSlide();
      if (!source) return;
      const copy = normalizeCreativeSlide({
        ...cloneCreativeEditorValue(source, {}),
        id: createCreativeEditorId("slide"),
        name: `${source.name || "Diapositiva"} copia`,
        elements: safeArray(source.elements).map((element) => ({ ...cloneCreativeEditorValue(element, {}), id: createCreativeEditorId(element.type || "el") })),
      }, draft.slides.length);
      const index = draft.slides.findIndex((slide) => slide.id === source.id);
      draft.slides.splice(index + 1, 0, copy);
      draft.activeSlideId = copy.id;
      draft.activeElementId = copy.elements[0]?.id || null;
    });
  }

  deleteSlide(id) {
    if (this.state.slides.length <= 1) {
      toast("Debe quedar al menos una diapositiva.", "warn");
      return;
    }
    this.mutate((draft) => {
      const targetId = id || draft.activeSlideId;
      draft.slides = draft.slides.filter((slide) => slide.id !== targetId);
      draft.activeSlideId = draft.slides[0]?.id || null;
      draft.activeElementId = draft.slides[0]?.elements?.[0]?.id || null;
    });
  }

  addElement(type, overrides = {}) {
    this.mutate(() => {
      const slide = this.activeSlide();
      if (!slide) return;
      const maxZ = Math.max(0, ...slide.elements.map((element) => numberOr(element.zIndex, 0)));
      const element = makeCreativeElement(type, { zIndex: maxZ + 1, ...overrides });
      slide.elements.push(element);
      this.state.activeElementId = element.id;
    });
  }

  addImage(src) {
    this.mutate(() => {
      const slide = this.activeSlide();
      if (!slide) return;
      const maxZ = Math.max(0, ...slide.elements.map((element) => numberOr(element.zIndex, 0)));
      const source = findCreativeImageSourceBySrc(src);
      const element = makeCreativeElement("image", {
        src,
        originalSrc: src,
        zIndex: maxZ + 1,
        x: 320,
        y: 86,
        width: 300,
        height: 210,
        sourceAssetId: source?.sourceType === "asset" ? source.id : "",
        sourceGalleryItemId: source?.sourceType === "gallery" ? source.id : "",
        metadata: { sourceItemId: source?.id || "", sourceType: source?.sourceType || "" },
      });
      slide.elements.push(element);
      this.state.activeElementId = element.id;
    });
  }

  applyPhotoSource(src) {
    const source = findCreativeImageSourceBySrc(src);
    this.mutate(() => {
      const slide = this.activeSlide();
      if (!slide) return;
      const element = this.activeElement();
      if (element?.type === "image") {
        element.src = src;
        element.originalSrc = src;
        element.renderMode = "original";
        element.renderedAssetId = "";
        element.sourceAssetId = source?.sourceType === "asset" ? source.id : "";
        element.sourceGalleryItemId = source?.sourceType === "gallery" ? source.id : "";
        element.metadata = {
          ...(element.metadata || {}),
          sourceItemId: source?.id || element.metadata?.sourceItemId || "",
          sourceType: source?.sourceType || element.metadata?.sourceType || "",
          renderedGalleryItemId: "",
        };
        return;
      }
      const maxZ = Math.max(0, ...slide.elements.map((item) => numberOr(item.zIndex, 0)));
      const next = makeCreativeElement("image", {
        src,
        name: source?.name || "Imagen editable",
        zIndex: maxZ + 1,
        x: 320,
        y: 86,
        width: 300,
        height: 210,
        originalSrc: src,
        sourceAssetId: source?.sourceType === "asset" ? source.id : "",
        sourceGalleryItemId: source?.sourceType === "gallery" ? source.id : "",
        metadata: { sourceItemId: source?.id || "", sourceType: source?.sourceType || "" },
      });
      slide.elements.push(next);
      this.state.activeElementId = next.id;
    });
  }

  async renderActivePhotoInstance() {
    const slide = this.activeSlide();
    const element = this.activeElement();
    if (!slide || !element || element.type !== "image" || !element.src) {
      toast("Selecciona una imagen dentro de la diapositiva para renderizar esa copia.", "warn");
      return null;
    }
    const source = findCreativeImageSourceBySrc(element.src);
    const originalSourceUrl = element.originalSrc || element.src;
    const sourceImageDataUrl = String(originalSourceUrl || "").startsWith("data:image") ? originalSourceUrl : "";
    if (!sourceImageDataUrl) {
      toast("Esta imagen necesita estar guardada como dataUrl del proyecto para renderizar la instancia.", "warn");
      return null;
    }
    const renderSettings = {
      style: element.photoSettings?.style || element.photoSettings?.finish || "photographic",
      fidelity: element.photoSettings?.fidelity || "strict",
      light: element.photoSettings?.light || "natural",
      changeRequest: element.photoSettings?.changeRequest || element.photoSettings?.prompt || "",
      provider: element.photoSettings?.provider || state.projectUi.imageProvider || "auto",
    };
    const prompt = buildBrochurePhotoPrompt({ ...element, photoSettings: { ...(element.photoSettings || {}), ...renderSettings } }, slide);
    assertPromptContract(prompt, "brochureImageLayer");
    toast("Renderizando la foto seleccionada para esta diapositiva...", "info");
    try {
      const response = await apiRequest("/api/brochure/render-image-layer", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          projectId: state.projects.activeId,
          presentationId: this.state.id || "creative-deck",
          slideId: slide.id,
          layerId: element.id,
          slotInstanceId: element.slotInstanceId,
          sourceAssetId: source?.id || element.sourceAssetId || element.sourceGalleryItemId || "",
          sourceImageDataUrl,
          prompt,
          contractName: "brochureImageLayer",
          renderSettings,
          slideContext: {
            slideType: slide.sectionId,
            layoutVariantId: slide.layout,
            name: slide.name,
          },
          layerContext: {
            role: element.role,
            name: element.name,
            width: element.width,
            height: element.height,
          },
        }),
      });
      const payload = await response.json();
      if (!response.ok || !payload?.ok || !payload.renderedAsset) {
        throw new Error(payload?.message || "No se pudo renderizar la imagen seleccionada.");
      }
      const promptTrace = createPromptTrace({
        module: "brochureStudio",
        provider: payload.renderedAsset.provider || payload.provider || "local",
        model: payload.renderedAsset.metadata?.model || inferPromptModel(payload.renderedAsset.provider || payload.provider || "local"),
        prompt,
        sourceAssetIds: [source?.sourceType === "asset" ? source.id : element.sourceAssetId].filter(Boolean),
        visualInventory: buildVisualInventoryFromAnalysis(source?.analysis || source?.metadata?.analysis || null),
        userOptions: renderSettings,
        userFeedback: renderSettings.changeRequest || "",
        stage: {
          presentationId: this.state.id || "creative-deck",
          slideId: slide.id,
          layerId: element.id,
          slotInstanceId: element.slotInstanceId,
        },
        parentOutputId: element.renderedAssetId || null,
        contractName: "brochureImageLayer",
      });
      const galleryItem = addProjectGalleryItem(state.project, {
        ...payload.renderedAsset,
        parentAssetIds: source?.sourceType === "asset" && source.id ? [source.id] : [element.sourceAssetId].filter(Boolean),
        parentGalleryItemIds: source?.sourceType === "gallery" && source.id ? [source.id] : [element.sourceGalleryItemId].filter(Boolean),
        metadata: {
          ...promptTrace,
          ...(payload.renderedAsset.metadata || {}),
          stage: "brochure-photo-instance",
          slideId: slide.id,
          elementId: element.id,
          slotInstanceId: element.slotInstanceId,
          photoSettings: cloneCreativeEditorValue(element.photoSettings || {}, {}),
        },
      });
      this.mutate(() => {
        const current = this.activeElement();
        if (!current || current.type !== "image") return;
        current.originalSrc = current.originalSrc || originalSourceUrl;
        current.src = galleryItem.url || galleryItem.dataUrl || current.src;
        current.renderedAssetId = galleryItem.id;
        current.renderMode = "rendered";
        current.renderSettings = renderSettings;
        current.renderHistory = [
          ...safeArray(current.renderHistory),
          { renderedAssetId: galleryItem.id, renderSettings, createdAt: new Date().toISOString() },
        ];
        current.metadata = {
          ...(current.metadata || {}),
          renderedGalleryItemId: galleryItem.id,
          sourceType: "gallery",
        };
      });
      toast("Foto renderizada y guardada en Gallery.", "ok");
      return galleryItem;
    } catch (error) {
      toast(error.message || "No se pudo renderizar la imagen seleccionada.", "error");
      return null;
    }
  }

  applyTemplate(templateId) {
    this.mutate(() => {
      const slide = this.activeSlide();
      if (!slide) return;
      const mappedType = BROCHURE_SLIDE_TYPES[templateId] ? templateId : "cover";
      const variant = BROCHURE_SLIDE_TYPES[mappedType].variants[0];
      const next = createSlideFromVariant(mappedType, variant.id, slide);
      Object.assign(slide, next);
      this.state.activeElementId = slide.elements.find((element) => element.type === "text")?.id || slide.elements[0]?.id || null;
    });
  }

  applyLocalTemplateSlide(layoutId) {
    this.mutate(() => {
      const slide = this.activeSlide();
      if (!slide) return;
      const oldText = safeArray(slide.elements).filter((element) => element.type === "text").map((element) => element.content).filter(Boolean);
      const title = oldText[0] || slide.name || state.settings.contextBrief || "Titulo del proyecto";
      slide.layout = layoutId || "tpl-page-1";
      slide.elements = buildCreativeTemplateElementsFromLocalTemplateSlide(slide.layout, {
        title,
        subtitle: oldText[1] || state.settings.brochureIdea || "Edita esta lamina por capas.",
        bullets: oldText.slice(2).length ? oldText.slice(2) : ["Texto editable", "Imagen separada", "Formas independientes"],
        images: getCreativeEditorImages(),
        palette: getCreativeEditorPalette(),
        sectionId: slide.sectionId,
        blueprintKey: slide.sectionId,
      });
      this.state.activeElementId = slide.elements[0]?.id || null;
    });
  }

  setSlideBackground(background) {
    this.mutate(() => {
      const slide = this.activeSlide();
      if (slide) slide.background = background;
    });
  }

  updateActiveElement(path, value) {
    this.mutate(() => {
      const element = this.activeElement();
      if (!element) return;
      const numericProps = new Set(["x", "y", "width", "height", "opacity", "rotation", "zIndex", "style.fontSize", "style.borderRadius"]);
      const finalValue = numericProps.has(path) ? numberOr(value, path === "opacity" ? 1 : 0) : value;
      const parts = path.split(".");
      let target = element;
      for (let index = 0; index < parts.length - 1; index += 1) {
        target[parts[index]] = target[parts[index]] || {};
        target = target[parts[index]];
      }
      target[parts[parts.length - 1]] = finalValue;
    });
  }

  toggleTextStyle(prop, activeValue, inactiveValue) {
    this.mutate(() => {
      const element = this.activeElement();
      if (!element || element.type !== "text") return;
      element.style = element.style || {};
      element.style[prop] = element.style[prop] === activeValue ? inactiveValue : activeValue;
    });
  }

  deleteActiveElement() {
    this.mutate(() => {
      const slide = this.activeSlide();
      if (!slide) return;
      slide.elements = slide.elements.filter((element) => element.id !== this.state.activeElementId);
      this.state.activeElementId = slide.elements[0]?.id || null;
    });
  }

  shiftLayer(direction) {
    this.mutate(() => {
      const element = this.activeElement();
      if (!element) return;
      element.zIndex = Math.max(1, numberOr(element.zIndex, 1) + direction);
    });
  }

  setZoom(value) {
    this.mutate((draft) => { draft.zoom = clamp(numberOr(value, 72), 45, 120); }, { history: false });
  }

  undo() {
    if (this.historyIndex <= 0) return;
    this.historyIndex -= 1;
    this.state = cloneCreativeEditorValue(this.history[this.historyIndex], {});
    this.render();
    this.sync();
  }

  redo() {
    if (this.historyIndex >= this.history.length - 1) return;
    this.historyIndex += 1;
    this.state = cloneCreativeEditorValue(this.history[this.historyIndex], {});
    this.render();
    this.sync();
  }

  async export(kind) {
    this.sync();
    if (kind === "images") {
      await exportCreativeDeckImages(this.serialize());
      return;
    }
    state.result.deck = await buildDeckFromCreativeEditorExportDeck(this.serialize());
    await downloadPdfVariant(kind === "ppt" ? "alternate" : "final");
  }
}

window.CreativeDeckEditor = CreativeDeckEditor;

function mountCanvaEditor() {
  ensurePdfBuilderDefaults();
  const blueprints = computePdfSlideBlueprints();
  if (!blueprints.length) {
    elements.pdfSectionStudio.innerHTML = `<div class="empty-state compact-empty"><strong>Primero define las diapositivas del brochure</strong><span>En el paso 4 escoges cantidad, tipo, orden y amenidades.</span></div>`;
    return;
  }
  const analysis = getPdfDeckAnalysis();
  const initialState = buildCreativeEditorInitialState(blueprints, analysis);
  const mountHash = JSON.stringify({
    slides: blueprints.map((blueprint) => blueprint.key),
    saved: state.settings.deckEditor?.slides?.length || 0,
  });
  if (window._creativeDeckEditorInst && window._creativeDeckEditorInst.mountEl === elements.pdfSectionStudio && window._creativeDeckEditorHash === mountHash) {
    return;
  }
  if (window._renderAIEditorInst) {
    window._renderAIEditorInst.unmount();
    window._renderAIEditorInst = null;
  }
  if (window._creativeDeckEditorInst) {
    window._creativeDeckEditorInst.unmount();
    window._creativeDeckEditorInst = null;
  }
  const inst = new CreativeDeckEditor(elements.pdfSectionStudio, initialState);
  inst.mount();
  window._creativeDeckEditorInst = inst;
  window._creativeDeckEditorHash = mountHash;
}
